entries[219381] = { ["name"] = "Schicksalsweber", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nIn Schildhand geführt\n+394 Intelligenz\n+208 Ausdauer\nErhöht Eure Tempowertung um + 125.\n+ 114 Vielseitigkeit\n\"Am Griff sind kaum leserliche Worte eingraviert: \"Die Ritualstätte befindet sich in Azj-Kahet und überblickt die Salinengossen, weit im Norden von Rak-Zakaz.\"\"\nVerkaufspreis:" }
entries[219382] = { ["name"] = "Schicksalsgewobene Nadel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n98 - 164 Schaden Geschwindigkeit 1.80\n(72.8 Schaden pro Sekunde)\n+748 Intelligenz\n+208 Ausdauer\nHaltbarkeit 80 / 80\nAnlegen: Eure schädlichen und hilfreichen Zauber haben eine Chance, für 5 Sek. einen Schicksalsfaden zwischen Euch und Eurem Ziel zu weben. Angeleinte Verbündete erhalten einen Bonus von 299 auf Ihren Primärwert, solange der Faden hält, und Gegner erleiden ( 1 * 8615 ) kosmischen Schaden, wenn der Faden reißt.\nVerkaufspreis:" }
entries[219383] = { ["name"] = "Umhang des irdenen Reisenden", ["text"] = "Wird beim Aufheben gebunden\nRücken\n236 Rüstung\n+230 [Beweglichkeit oder Stärke oder Intelligenz]\n+636 Ausdauer\nErhöht Eure Tempowertung um + 219.\nErhöht Eure Meisterschaftswertung um + 169.\nVerkaufspreis:" }
entries[219384] = { ["name"] = "Tenir und der Orden der Nacht", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein zehnstündiges Epos in drei Akten.\"" }
entries[219385] = { ["name"] = "Lähmungsheilserum", ["text"] = "Questgegenstand\nBenutzen: Verabreicht das Lähmungsheilserum einem Ziel, das durch den Trank des Strippenziehers gelähmt wurde.\n\"Eine Serum zum Heilen von Lähmungen. Die Wirksamkeit kann nicht garantiert werden.\"" }
entries[219386] = { ["name"] = "Locus der Macht", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nLocus der Macht\nKanalisiert arkane Macht für 4 Sek. Alle 0.40 Sek. werden bei Euch und 2 Verbündeten innerhalb von 50 Metern 30 Sek. lang das Tempo, der kritische Trefferwert und die Meisterschaft erhöht.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[219387] = { ["name"] = "Fass mit Feuerwerkskörpern", ["text"] = "Spielzeug\nBenutzen: Stellt ein gefährliches Fass mit Feuerwerkskörpern auf, das 5 Min. Sek. lang stehen bleibt, um für Euch und Eure Freunde den Nachthimmel grell zu erleuchten!\n\nAndere Spielercharaktere können sich das Feuerwerk auch ansehen, indem sie das Fass angreifen.\n\nWährend der Feierlichkeiten von betrunkenen Goblins ist die Abklingzeit verringert. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[219388] = { ["name"] = "Fackel der Heiligen Flamme", ["text"] = "Questgegenstand\nBenutzen: Bringt eine Gruppe Arathi in der Nähe durch ihren Glauben an die Heilige Flamme zusammen!\n\"Die Fackel brennt hell. Das Knistern und Flackern klingt fast schon musikalisch.\"" }
entries[219389] = { ["name"] = "Blitzableiter", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten haben eine Chance, Euer Ziel mit 'Blitzableiter' zu belegen. Der kritische Trefferwert von Verbündeten wird 10 Sek. lang erhöht und Gegner erleiden 8 Sek. lang alle 2 Sek. Naturschaden. Wenn 'Blitzableiter' abläuft, kehrt er zu Euch zurück und erhöht 10 Sek. lang Euren kritischen Trefferwert.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[219390] = { ["name"] = "Schlüsselsteinkarte festlegen: Grim Batol", ["text"] = "Dauer: 12 std. (Realzeit)\nBenutzen: Legt Grim Batol als Dungeon für einen mythischen Schlüsselstein fest.\nVerkaufspreis:" }
entries[219391] = { ["name"] = "Luftschiff des Tiefenforschers", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Luftschiff des Tiefenforschers oder gibt es wieder frei.\n\nBei diesem Transportmittel kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mit diesem Luftfahrzeug könnt Ihr Euch direkt ins Abenteuer stürzen, wo immer es auch sein mag!\"\nQuest:\nAbtauchen\nZone:\nInsel von Dorn" }
entries[219392] = { ["name"] = "Flammenfluss 7000", ["text"] = "Questgegenstand\nBenutzen: Holt einen Flammenwerfer hervor und verursacht 3 Sek. lang Feuerschaden in einem kegelförmigen Bereich vor Euch. Wirkt gegen die invasiven Nestbauer von Mmarl. (6 Sek. Abklingzeit)\n\"Mit Gazlowes Flammenwerfer lassen sich die Käfer in der Höhle von Mmarl garantiert beeindrucken.\"" }
