entries[219450] = { ["name"] = "Bezaubernder Kurier", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört den bezaubernden Kurier oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Weder Schnee noch Regen noch Hitze noch das Dunkel der Nacht können diese bezaubernden Kuriere davon abhalten, geflissentlich und zügig ihre Runden zu drehen.\"\nWoW-Shop" }
