entries[219489] = { ["name"] = "Watstiefel der vereinigenden Flamme", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n1964 Rüstung\n+1.597 [Beweglichkeit oder Intelligenz]\n+7.311 Ausdauer\nErhöht Eure Tempowertung um + 624.\nErhöht Eure Meisterschaftswertung um + 468.\nHaltbarkeit 80 / 80\nAnlegen: Beim Heilen eines Verbündeten besteht eine Chance, dass Ihr beide eine vereinigende Glut erhaltet. Wenn sich zwei vereinigende Gluten berühren, brechen 'Vereinigende Flammen' daraus hervor.\n\n'Vereinigende Flammen' erhöht den höchsten Sekundärwert des Trägers um 1175 und bei anderen einen zufälligen Sekundärwert um 235 .\nVerkaufspreis:" }
entries[219492] = { ["name"] = "Geheiligter Handschutz des Fackelträgers", ["text"] = "Wird beim Aufheben gebunden\nHände Kette\n2606 Rüstung\n+1.597 [Beweglichkeit oder Intelligenz]\n+7.311 Ausdauer\nErhöht Eure kritische Trefferwertung um + 624.\nErhöht Eure Meisterschaftswertung um + 468.\nHaltbarkeit 55 / 55\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, die Kraft des Lichts auf Eure Gegner herabzurufen. Ein Funke von Beledar richtet und markiert sie und fügt ihnen 86350 Strahlenschaden zu. Euer nächster Funke gegen Euer Ziel verbraucht das Mal, um 74015 zusätzlichen Strahlenschaden zu verursachen.\nVerkaufspreis:" }
