entries[219501] = { ["name"] = "Unterarmschienen der vordringenden Dunkelheit", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Kette\n2317 Rüstung\n+1.198 [Beweglichkeit oder Intelligenz]\n+5.483 Ausdauer\n+ 351 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 468.\nHaltbarkeit 55 / 55\nAnlegen: Wenn Ihr Schaden verursacht, besteht eine Chance, einen Stapel von 'Verfinsternde Dunkelheit' zu erhalten. Bei 5 Stapeln explodiert die Dunkelheit und verursacht ( 1 * 161232 ) Schattenschaden, die auf alle Gegner in der Nähe aufgeteilt werden. Der Schaden erhöht sich pro Ziel für maximal 5 Ziele. Danach legen sich die Schatten auf Euch und verringern Eure Bewegungsgeschwindigkeit 5 Sek. lang um 15%.\n\nDies ist eine nerubische Verzierung.\nVerkaufspreis:" }
entries[219502] = { ["name"] = "Schnalle des Adrenalinschubs", ["text"] = "Wird beim Aufheben gebunden\nTaille Leder\n1767 Rüstung\n+1.597 [Beweglichkeit oder Intelligenz]\n+7.311 Ausdauer\nErhöht Eure kritische Trefferwertung um + 624.\n+ 468 Vielseitigkeit\nHaltbarkeit 55 / 55\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass Ihr 'Adrenalinschub' erhaltet, sodass Eure Hauptwert um 1265 erhöht, Eure Meisterschaft aber um 207 verringert wird. Hält 12 Sek. lang an.\n\nDies ist eine nerubische Verzierung. (15s Abklingzeit)\nVerkaufspreis:" }
