entries[219905] = { ["name"] = "Donnernde Trommeln", ["text"] = "Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder ähnlichen Effekten profitieren. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[219915] = { ["name"] = "Beißwerkzeug des besudelten Behemoths", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 [Beweglichkeit oder Stärke]\nBenutzen: Injiziert einem Gegner ein Verdauungsgift und fügt ihm im Verlauf von 20 Sek. 617919 Naturschaden zu. Solange es aktiv ist, stellen Eure Angriffe und Fähigkeiten gegen das Ziel 32184 Gesundheit wieder her. Kann nur ein Mal pro Sekunde auftreten.\n\nÜberheilung durch diesen Effekt erhöht dauerhaft Eure maximale Gesundheit um den gleichen Wert. Der Effekt wird nach Verlassen des Kampfes in ein Absorptionsschild umgewandelt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[219916] = { ["name"] = "Kompass der Familie Bronzebart", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 1.171.\nBenutzen: Orientiert Euch und trefft Euch mit Brann, der heldenhaft heranrauscht und '' einsetzt. Er verursacht dadurch 1769479 körperlichen Schaden und gewährt Euch dann 10 Sek. lang 19525 Hauptwert, bevor er wieder verschwindet.\n\nSollte Brann bereits an Euer Seite sein, wird er Euch stolz den Weg zum Abenteuer weisen! Dafür bewegt er sich an eine andere Stelle, verleiht sich selbst 10 Sek. lang 50% zusätzlichen Schaden und setzt '' ein.\n\n: (2 Min Abklingzeit)\n\"Ein Symbol für Abenteuer, Entdeckung und Kameraderie. Wurde Euch von Brann Bronzebart persönlich anvertraut.\"\nVerkaufspreis:" }
entries[219917] = { ["name"] = "Kriechendes Koagulum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 Intelligenz\nBenutzen: Füttert das Koagulum und leitet 20% sämtlicher hervorgerufener Heilung um bis ( 2828996 * 40 / 100) Heilung aufgezehrt wurde. Ist es gesättigt, bricht das Koagulum auf und heilt 5 Verbündete um [Quellwert] Gesundheit.\n\nAnhaltende Ausdünstungen lassen die nächsten Angriffe betroffener Verbündeter basierend auf der überschüssigen Heilung durch das Koagulum 20151 zusätzlichen Schattenschaden verursachen. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[219919] = { ["name"] = "Klinge des Hasses", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n453 - 756 Schaden Geschwindigkeit 2.60\n(232.5 Schaden pro Sekunde)\n+205 Beweglichkeit\n+566 Ausdauer\nErhöht Eure kritische Trefferwertung um + 187.\n+ 158 Vielseitigkeit\nHaltbarkeit 90 / 90\nKlassen: Hexenmeister , Dämonenjäger\nAnlegen: Verursachter Feuerschaden hat eine Chance, 'Wutentbrannter Hass' zu gewähren, was im Verlauf von 9 Sek. [Quellwert] Schattenschaden verursacht, die zwischen dem Ziel und anderen Gegnern in der Nähe aufgeteilt werden.\n\nDer Schaden steigt mit jedem getroffenen Gegner an, bis zu 5 Gegner.\nVerkaufspreis:", ["unresolvedValues"] = true }
