entries[220117] = { ["name"] = "Schutz der Errettung", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nSchutz der Errettung\nStellt bei einem Verbündeten Gesundheit wieder her und gewährt ihm 8 Sek. lang 'Schutz der Errettung'.\n\nSolange 'Schutz der Errettung' anhält, gewährt die durch den Zaubernden erhaltene Heilung zusätzlich Absorption.\n\nWenn der Schutz abläuft, explodiert er und fügt allen Gegnern innerhalb von 40 Metern Heiligschaden in Höhe der verbleibenden Absorption zu, der gleichmäßig aufgeteilt wird.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[220118] = { ["name"] = "Detonationsladung der Arathi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.045 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Wirft ein Sprengstofffass ab, um Gegner von Arathor mit rechtschaffenen Flammen zu überziehen, die ( 1 * 367648 ) Feuerschaden verursachen, die auf alle Gegner im Radius der Explosion aufgeteilt werden. (2 Min Abklingzeit)\n\"Wenn die Lunte entzündet wird, solltet Ihr Sir Explosivo als Außenseiter betrachten. - In den Hallen der Lichtfunkenakademie gehört\"\nVerkaufspreis:" }
