entries[220120] = { ["name"] = "Seelenbindung", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nSeelenbindung\nVerbindet Eure Seele 1 Stunde lang mit der eines Verbündeten, um 20% seines erlittenen Schadens als Schattenschaden auf Euch umzuleiten. Dieser Effekt kann auf bis zu 5 Verbündete angewendet werden. Wenn Ihr dies auf einen bereits verbundenen Verbündeten anwendet oder Euch mehr als 100 Meter von ihm entfernt, wird der Effekt aufgehoben.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[220122] = { ["name"] = "Opfergabe aus reinem Wasser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ihr kombiniert eine Opfergabe aus reinem Wasser mit einem Krug voller Schleim.\n\"Keine Unreinheit trübt dieses kristallklare Wasser. Ihr könnt hindurchsehen, als wäre in dem Glas überhaupt nichts drin.\"\nVerkaufspreis:" }
