entries[220134] = { ["name"] = "Trödelnder Häsling", ["text"] = "Benutzen: Wirft den Fisch zurück ins Wasser, um Eure Angelfertigkeit 30 Sek. lang um 10 zu erhöhen.\n\nDurch das Zurückwerfen mehrerer Fische kann diese Stärkung auf bis zu 5 Min. verlängert werden.\nHandwerksmaterial\n\"Ein gewöhnlicher Fisch aus Khaz Algar. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
