entries[220152] = { ["name"] = "Verfluchter Geisterfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Werft diesen Fisch ins Wasser zurück, was den Geisterfischfluch läutert und 15 Min. lang 15 Wahrnehmung verleiht.\nHandwerksmaterial\n\"Ein seltener Fisch, der in Khaz Algar gefangen werden kann. Kann nicht im Auktionshaus verkauft oder erworben werden.\"\nVerkaufspreis:" }
