entries[220156] = { ["name"] = "Blubberndes Wachs", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Überzieht Eure Waffen mit einem blubbernden Wachs, das bis Abbruch lang anhält. Wenn Ihr giftige Effekte auf Euer Ziel anwendet, besteht die Chance, dass eine Lache aus kochendem Wachs von 4 Metern über dem Ziel ausgeschüttet wird, die 87854 Feuerschaden verursacht, der auf die Gegner aufgeteilt wird.\n\nDer Schaden wird für jeden getroffenen Gegner erhöht, bis zu 5 Gegner.\nVerkaufspreis:" }
entries[220157] = { ["name"] = "Ermächtigter Zunderkasten", ["text"] = "Wird beim Aufheben gebunden\nHals\n+636 Ausdauer\nErhöht Eure kritische Trefferwertung um + 732.\n+ 582 Vielseitigkeit\nVerkaufspreis:" }
