entries[220161] = { ["name"] = "Geronnene Blutstifte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine verdächtig ekelhaft aussehende Kerze. (5 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:" }
entries[220172] = { ["name"] = "Unvergessener Machtkristall", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\n\"Die verschwommenen Formen dieser unvergessenen Kristalle flackern in einem Kaleidoskop der Farben, stets wechselnd zwischen Rot, Grün, Blau und Gelb.\"" }
entries[220202] = { ["name"] = "Netz des Meisterspions", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 1.001.\nAnlegen: Eure Schadenszauber entsenden eine Spinne, die Eure Feinde ausspioniert und Eure Intelligenz pro erhaltenem Bericht um 45 erhöht. Bis zu 40-mal stapelbar. Dieser Effekt kann nur alle 6 Sek. auftreten. (6s Abklingzeit)\nBenutzen: Nutzt Euer angesammeltes Wissen, um im richtigen Moment zuzuschlagen, wodurch 416 Intelligenz pro Bericht für 20 Sek. gewährt wird und ihren passiven Effekt aufbraucht. (20 Sek. Abklingzeit)\nVerkaufspreis:" }
