entries[220211] = { ["name"] = "Rand des Wahnsinns", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nRand des Wahnsinns\nUmhüllt Eure Gruppenmitglieder innerhalb von 40 Metern mit Leere, was ihnen einen Schild gewährt, der 20 Sek. lang Schaden absorbiert und ihre Gesundheit auf 10% verringert. Erlittener Schaden aus diesem Effekt wird der Absorption hinzugefügt.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
