entries[220304] = { ["name"] = "Verwittertes Nordendsiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Fähigkeiten haben eine Chance, die Macht der Völker von Nordend zu erwecken, wodurch Ihr vorübergehend transformiert werdet und Eure Kampffähigkeiten 30 Sek. lang erhöht werden. (Procchance: 35%, 1.75Min. Abklingzeit)\nVerkaufspreis:" }
entries[220305] = { ["name"] = "Ovi'nax' quecksilbriges Ei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Balanciert sorgfältig die Bebrütung des Eis aus. Bei Stillstand erhaltet Ihr alle 1 Sek. 100 Hauptwert, bis zu 30-mal. Schwindet bei Bewegung. Bei Bewegung erhaltet Ihr alle 1 Sek. 114 Eures höchsten Sekundärwerts, bis zu 30-mal. Schwindet bei Stillstand.\n\nWeitere Stapel nach dem 20. Stapel gewähren 60% verringerte Vorteile.\nBenutzen: Unterbricht den Inkubationszustand des Eis für 20 Sek. (2 Min Abklingzeit)\nVerkaufspreis:" }
