entries[221263] = { ["name"] = "Nerubischer Giftpfeil", ["text"] = "Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure Distanzangriffe haben eine Chance dem Ziel ein lähmendes Gift zu injizieren, das im Verlauf von 9 Sek. ( 1 * 23329 ) Naturschaden verursacht.\n\nFür jede Sekunde, in der sich das betroffene Ziel bewegt, erhaltet Ihr 10 Sek. lang ( 254 / 5) Tempo. Bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[221264] = { ["name"] = "Bündel des Fungianermystikers", ["text"] = "Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber haben eine Chance, Sporen freizusetzen, die 4 Verbündeten in der Nähe für 10 Sek. 566 Meisterschaft gewähren. Alle Sporen, die keinen Wirt finden, gewähren stattdessen Euch 80% Meisterschaft.\n\nWird dieser Effekt durch einen Naturzauber ausgelöst, wird eine zusätzliche Spore freigesetzt.\nVerkaufspreis:" }
entries[221265] = { ["name"] = "Amulett der Untergrundbestie", ["text"] = "Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber haben eine Chance, die animalischen Erkenntnisse des Amuletts wachzurufen, die Euren kritischen Trefferwert 12 Sek. lang um 1115 erhöhen.\n\nWenn Ihr gegen ein Tier oder an der Seite eines Tiers kämpft, ist dieser Effekt um 20% erhöht.\nVerkaufspreis:" }
entries[221268] = { ["name"] = "Beutel verwitterter Vorbotenwappen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 verwitterte Vorbotenwappen. Für diese Wappen gilt das Saisonlimit nicht.\nSchließt die Quest \"Der Vorbote unter den Wappen\" von Vaskarn in Dornogal ab, um Eure Vorbotenwappen abwerten zu können." }
entries[221269] = { ["name"] = "Blutroter Tapferkeitsstein", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 100 Tapferkeitssteine.\"\n<Zum Öffnen rechtsklicken>" }
entries[221270] = { ["name"] = "Cooler Kezanischer Wellenschredder", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen coolen Kezanischen Wellenschredder oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wenn jeder einen Ozean hätte, würde jeder auf diesem erstklassigen Wellenschredder surfen gehen. Und wenn man keinen Ozean hat, kann man damit einfach durch die Lüfte surfen!Hang 8!\"\nWoW-Shop" }
entries[221373] = { ["name"] = "Säckchen geschnitzter Vorbotenwappen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 geschnitzte Vorbotenwappen. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Der Vorbote unter den Wappen\" von Vaskarn in Dornogal ab, um Eure Vorbotenwappen abwerten zu können." }
entries[221375] = { ["name"] = "Bündel runenverzierter Vorbotenwappen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 runenverzierte Vorbotenwappen. Für diese Wappen gilt das Saisonlimit nicht.\nSchließt die Quest \"Der Vorbote unter den Wappen\" von Vaskarn in Dornogal ab, um Eure Vorbotenwappen abwerten zu können.\nSchließt die Quest \"Nicht die Wappen untergraben\" von Vaskarn in Dornogal ab, um Eure Lorenhallwappen abwerten zu können." }
