entries[221751] = { ["name"] = "Prismatischer Kodex", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nutzt den prismatischen Kodex, um die Inhalte eines Erinnerungsedelsteins anzusehen. (30 Sek. Abklingzeit)\n\"Ein tragbares Gerät mit einem einzelnen Platz für einen Erinnerungsedelstein eines Irdenen. Verwendet es, um eine einzelne Erinnerung aus dem Edelstein abzuspielen.\"" }
entries[221753] = { ["name"] = "Qualmende Glutbiene", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 16 beim Rat von Dornogal.\nBenötigt Ruhmrang 23 beim Rat von Dornogal.\n\n\"Eine recht überraschende Wahl für ein Reittier, doch der Rat von Dornogal versichert Euch, dass es sicher ist, es zu reiten. Meistens jedenfalls...\"\nVerkäufer:\nAuditor Balwurz\nZone:\nDornogal\nKosten:\n11.375" }
entries[221754] = { ["name"] = "Barren der Schallenden Tiefen", ["text"] = "Handwerksmaterial\n\"Eine meisterhaft geschmiedete Tafel aus algarischem Metall, robust und doch formbar. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
