entries[221756] = { ["name"] = "Phiole voll Kahetiölen", ["text"] = "Handwerksmaterial\n\"Eine Fusion alchemistischer Gespinste und kunsthandwerklicher Fertigkeit. Die dunkle Alchemie der Kaheti. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
