entries[221848] = { ["name"] = "Tiberius", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ruhmrang 15 bei den Arathi von Heilsturz.\nBenötigt Kürschnerei von Khaz Algar und Ruhmrang 14 bei den Arathi von Heilsturz." }
entries[221849] = { ["name"] = "Vanille", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[221850] = { ["name"] = "Frisch gewebter Kebab", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Packt die noch zappelnde Delikatesse aus. Ihr könnt klagende Tierlaute aus dem Inneren hören.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[221851] = { ["name"] = "Argos' Glocke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[221871] = { ["name"] = "Prototyp: Trankbombe der Geschwindigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der ihre Bewegungsgeschwindigkeit 20 Sek. lang um 10-15% (je nach Herstellungsqualität) erhöht.\n\nVon der Explosion erfasste Gegner erleiden 67738 Feuerschaden, der zwischen ihnen aufgeteilt wird.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221875] = { ["name"] = "Prototyp: Trankbombe der Erholung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der die von ihnen erhaltene Heilung 12 Sek. lang um 5-10% (je nach Herstellungsqualität) erhöht.\n\nVon der Explosion erfasste Gegner erleiden 67738 Feuerschaden, der zwischen ihnen aufgeteilt wird.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221879] = { ["name"] = "Prototyp: Trankbombe der Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der deren Primärwert 30 Sek. lang um ( 2196 / 5) erhöht.\n\nVon der Explosion erfasste Gegner erleiden 67738 Feuerschaden, der zwischen ihnen aufgeteilt wird.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221903] = { ["name"] = "Prototyp: Tüftelei: Irdener Lieferbohrer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Beschwört einen irdenen Lieferbohrer, der nach verschiedenen Schlachtfeldstärkungen gräbt.\n\nDer Bohrer bleibt 28 Sek. lang aktiv und kann nur im Kampf beschworen werden. Sein Einsatz ist nur auf nicht gewerteten Schlachtfeldern und im Kriegsmodus auf Khaz Algar möglich. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221907] = { ["name"] = "Prototyp: Tüftelei: Herzsuchender Gesundheitsinjektor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Injiziert eine medizinische Frostfeuerformel in Eure Adern, die Euch durch einen Frostschock sofort um 1943637 heilt. Zur Verhinderung einer plötzlichen Unterkühlung brennt Ihr anschließend für 30% des geheilten Betrags.\n\nTeilt sich eine Abklingzeit mit Heiltränken.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221944] = { ["name"] = "Prototyp: Unwiderstehlicher roter Knopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Setzt ein Gerät ein, das von Euch oder einem Mitglied Eurer Gruppe bzw. Eures Schlachtzugs aktiviert werden kann, wenn eine Notlage droht. Wenn es aktiviert wird, versucht es, am Ende des Kampfes alle Verbündeten in der Nähe wiederzubeleben.\n\nHält 1 Stunde lang an oder bis es aktiviert wird. Muss vor dem Kampf eingesetzt werden.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221945] = { ["name"] = "Unwiderstehlicher roter Knopf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt ein Gerät ein, das von Euch oder einem Mitglied Eurer Gruppe bzw. Eures Schlachtzugs aktiviert werden kann, wenn eine Notlage droht. Wenn es aktiviert wird, versucht es, am Ende des Kampfes alle Verbündeten in der Nähe wiederzubeleben.\n\nHält 1 Stunde lang an oder bis es aktiviert wird. Muss vor dem Kampf eingesetzt werden.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221948] = { ["name"] = "Prototyp: Pausierender Pylon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Platziert einen pausierenden Pylonen, der die Stoffwechselprozesse von Spielercharakteren in seiner Nähe unterbricht und den Ablauf der Fläschchen, Phiolen und Sättigungseffekte von Khaz Algar anhält.\n\nDer Pylon ist äußert zerbrechlich und explodiert in der Gegenwart von Gewalt.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221949] = { ["name"] = "Pausierender Pylon", ["text"] = "Benutzen: Platziert einen pausierenden Pylonen, der die Stoffwechselprozesse von Spielercharakteren in seiner Nähe unterbricht und den Ablauf der Fläschchen, Phiolen und Sättigungseffekte von Khaz Algar anhält.\n\nDer Pylon ist äußert zerbrechlich und explodiert in der Gegenwart von Gewalt.\nVerkaufspreis:" }
entries[221952] = { ["name"] = "Prototyp: Täuschend echte Überbrückungskabel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Jagt einem \"toten\" Verbündeten Angst ein, indem Ihr ihm mit einem Elektroschock droht, und holt ihn so mit 35% Gesundheit und 10% Mana ins \"Leben\" zurück. Manchmal nimmt das Ziel Eure Drohung nicht ernst.\n\nKann im Kampf eingesetzt werden. Die Qualität des Gegenstands beeinflusst die Zauberzeit. Kann nicht von Spielercharakteren über Stufe 80 verwendet werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\n\"Manchmal tun sie nur so.\"\nVerkaufspreis:" }
entries[221956] = { ["name"] = "Prototyp: Algarischer Reparaturbot 11-O", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Setzt einen kleinen irdenen Golem ein, der Euch und Euren Gefährten erlaubt, Eure Ausrüstung zu reparieren.\n\nHält 10 Min. lang an.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221957] = { ["name"] = "Algarischer Reparaturbot 11-O", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt einen kleinen irdenen Golem ein, der Euch und Euren Gefährten erlaubt, Eure Ausrüstung zu reparieren.\n\nHält 10 Min. lang an.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221958] = { ["name"] = "Prototyp: Tragbarer Berufsmöglichkeitenprojektor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Beschwört einen Möglichkeitenprojektor, der für die Erfüllung der Anforderungen an Handwerkstische konfiguriert wurde. Es kann nur eine Werkbank gleichzeitig angezeigt und ausschließlich durch den Ingenieur ausgetauscht werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221959] = { ["name"] = "Tragbarer Berufsmöglichkeitenprojektor", ["text"] = "Benutzen: Beschwört einen Möglichkeitenprojektor, der für die Erfüllung der Anforderungen an Handwerkstische konfiguriert wurde. Es kann nur eine Werkbank gleichzeitig angezeigt und ausschließlich durch den Ingenieur ausgetauscht werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221960] = { ["name"] = "Prototyp: Fass mit Feuerwerkskörpern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Stellt ein gefährliches Fass mit Feuerwerkskörpern auf, das 5 Min. Sek. lang stehen bleibt, um für Euch und Eure Freunde den Nachthimmel grell zu erleuchten!\n\nAndere Spielercharaktere können sich das Feuerwerk auch ansehen, indem sie das Fass angreifen.\n\nWährend der Feierlichkeiten von betrunkenen Goblins ist die Abklingzeit verringert. (1 Stunde Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221961] = { ["name"] = "Prototyp: Defekte Rettungskapsel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Sucht dringend Schutz in einer defekten Rettungskapsel. Ihr kommt zwar nicht sehr weit, doch dafür seid Ihr in Sicherheit. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221962] = { ["name"] = "Defekte Rettungskapsel", ["text"] = "Spielzeug\nBenutzen: Sucht dringend Schutz in einer defekten Rettungskapsel. Ihr kommt zwar nicht sehr weit, doch dafür seid Ihr in Sicherheit. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[221963] = { ["name"] = "Prototyp: Filmlose Kamera", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Weckt Euer Fotografietalent! (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[221964] = { ["name"] = "Filmlose Kamera", ["text"] = "Spielzeug\nBenutzen: Weckt Euer Fotografietalent! (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[221965] = { ["name"] = "Prototyp: Wurmlochgenerator: Khaz Algar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen zufälligen Ort in Khaz Algar zu reisen. (30 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221966] = { ["name"] = "Wurmlochgenerator: Khaz Algar", ["text"] = "Spielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen zufälligen Ort in Khaz Algar zu reisen. (30 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:" }
entries[221967] = { ["name"] = "Meuteverprügler 2-30", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man den Meuteverprügler 2-30 beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Schlägt Euren Gegnern mit einem einzigen Hieb die Zähne aus. Garantiert!\"\nBeruf:\nIngenieurskunst von Khaz Algar" }
entries[221968] = { ["name"] = "Leserlich geschriebene Notizen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Ihr ordnet 15 leserlich geschriebene Notizen zu etwas Verständlichem an.\nBenötigt Ingenieurskunst von Khaz Algar (1)\n\"Kann von mehr als nur Heilern gelesen, aber nur von Ingenieuren verstanden werden.\"" }
entries[221969] = { ["name"] = "W.U.M.M.S. x2", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n3,365 - 6,251 Schaden Geschwindigkeit 3.00\n(1,603 Schaden pro Sekunde)\n+2.129 Beweglichkeit\n+9.748 Ausdauer\n+ 728 Zufallswert 1\n+ 728 Zufallswert 2\nHaltbarkeit 120 / 120\n\"Komm schon, schieß schneller!\"\nVerkaufspreis:" }
entries[221970] = { ["name"] = "Reines Kriecherextrakt", ["text"] = "Questgegenstand\n\"Eine grün leuchtende und von den Maschinenflüsterern außerordentlich geschätzte Flüssigkeit zur Entfernung von Rost.\"" }
entries[221977] = { ["name"] = "Scheiterhaufen", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nScheiterhaufen\nGewährt dem Zaubernden 1 Min. lang Hauptwert.\n\nBelegt den Zaubernden alle 1 Sek. mit einem Stapel 'Scheiterhaufen', wodurch er pro Stapel Feuerschaden erleidet.\n\n'Scheiterhaufen' wird vorzeitig entfernt, wenn der Effekt erneut aktiviert wird. (2 Min. Abklingzeit)\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
entries[221982] = { ["name"] = "Bollwerk des Schwarzen Ochsen", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Erlernt folgenden Zauber.\n\nBollwerk des Schwarzen Ochsen\nKanalisiert das Bollwerk des Schwarzen Ochsen. Stürmt auf einen Gegner zu und entfernt alle Betäubungs- und Bewegungsunfähigkeitseffekte, erhaltet einen Schaden absorbierenden Schild und verspottet Gegner innerhalb von 20 Metern. Fügt Gegnern innerhalb von 20 Metern 5 Sek. lang alle 1 Sekunden körperlichen Schaden plus 20% des vom Schild erlittenen Schadens zu.\n80 ( 80)\n\"Passt in einen Metasockel.\"" }
